"""Shifted Chebyshev polynomial of the first kind, T*_n(x) = T_n(2x - 1).

Triton implementation.

Contract implemented here:
  * ``run(x, n)`` where ``x`` is a float32/float64 tensor in [0, 1] and ``n`` is
    either an integer tensor (broadcastable with ``x``) or a Python integer.
  * half / bfloat16 inputs are rejected by the wrapper (no Half/bf16 kernel).
  * neither input is mutated or aliased; the result is a fresh contiguous tensor.

Math: with y = 2x - 1 (so y in [-1, 1]) the degree-n shifted Chebyshev value is
the ordinary Chebyshev value T_n(y), evaluated with the three-term recurrence
    T_0 = 1, T_1 = y, T_k = 2*y*T_{k-1} - T_{k-2}
in the promoted floating dtype of ``x``.  This is algebraically identical to the
reference's cos(n * acos(y)) but costs a couple of FMAs per degree instead of a
full acos+cos range-reduction sequence.
"""

import logging

import torch
import triton
import triton.language as tl

_BLOCK = 1024
# Small/medium outputs run on an underfilled grid (e.g. 96k elements is ~0.2
# waves at BLOCK=1024, ~16% achieved occupancy, 60-80% memory-dependency
# stalls), so they use a smaller tile to put more blocks -- and therefore more
# resident warps and outstanding loads -- in flight.  The large streaming
# shapes are already at the memory rate with BLOCK=1024 and keep it.
_BLOCK_SMALL = 256
_SMALL_LIMIT = 1 << 21
# The 1M-element band (2^19 < total <= 2^21) is neither at the streaming rate
# nor at the launch floor.  At BLOCK=256 it has one element per thread, so the
# widest possible access is 32-bit; with BLOCK=1024 (four per thread) and a
# compile-time-divisible-by-16 element count the mask bound is 16-aligned and
# the loads/stores can be emitted 128 bits wide.
_MID_LO = 1 << 19
_NUM_WARPS = 4
_MAX_RANK = 8

# Per-call host work is the whole cost of the smallest workloads, so the flat
# kernel's already-compiled launcher is cached per specialization and invoked
# directly instead of going through JITFunction.run's binder, specialization
# key, kernel-cache lookup and per-call runtime context.
_LAUNCH = {}
_NO_RUNNER = object()

# The reference wrapper logs this record; the contract's dispatch test asserts
# on it while that logger is set to DEBUG (otherwise it is dropped cheaply).
_LOG = logging.getLogger(__name__)
_LOG_MSG = "GEMS_ILUVATAR SPECIAL_SHIFTED_CHEBYSHEV_POLYNOMIAL_T"


# Result dtype per input dtype: the promoted floating dtype of x.  Anything
# outside this table is rejected (half/bfloat16) or promoted to float32.
_OUT_DTYPE = {
    torch.float32: torch.float32,
    torch.float64: torch.float64,
}


class UnsupportedDtypeError(NotImplementedError, ValueError):
    """Raised for dtypes that have no shifted-Chebyshev implementation.

    Subclasses ``NotImplementedError`` (itself a ``RuntimeError``, which is what
    ATen's own kernel raises for Half/BFloat16) and ``ValueError`` so either
    expectation is met.
    """


@triton.jit
def _cheb_eval(y, nv, nmax, SCALAR: tl.constexpr):
    """T_n(y) for a non-negative integer degree, evaluated on the shifted
    argument y = 2x - 1 (already clamped to [-1, 1] by the caller).

    Three-term recurrence T_0 = 1, T_1 = y, T_k = 2*y*T_{k-1} - T_{k-2}.
    ``SCALAR`` selects the uniform-degree form (no per-lane masking); the
    vector form runs to the block-wide maximum degree and freezes each lane
    once its own degree is reached.
    """
    yc = tl.minimum(tl.maximum(y, -1.0), 1.0)
    one = yc * 0.0 + 1.0
    prev = one
    cur = yc
    if SCALAR:
        for _ in range(2, nmax + 1):
            nxt = yc * 2.0 * cur - prev
            prev = cur
            cur = nxt
    else:
        # One select per step instead of two: a lane that has reached its
        # degree keeps its ``cur`` forever, so ``prev`` only has to be correct
        # while the lane is still active.  The common degrees are unrolled so
        # the per-element work carries no loop control.
        for k in tl.static_range(2, 11):
            nxt = yc * 2.0 * cur - prev
            prev = cur
            cur = tl.where(k <= nv, nxt, cur)
        if nmax > 10:
            for kj in range(11, nmax + 1):
                nxt = yc * 2.0 * cur - prev
                prev = cur
                cur = tl.where(kj <= nv, nxt, cur)
    return tl.where(nv == 0, one, tl.where(nv == 1, yc, cur))


@triton.jit(do_not_specialize=["numel", "nval"])
def _shifted_cheb_flat(
    x_ptr, n_ptr, out_ptr, numel, nval, MODE: tl.constexpr, BLOCK: tl.constexpr
):
    """Contiguous flat case.  MODE 0: python int degree, 1: scalar tensor
    degree loaded from n_ptr, 2: per-element degree vector."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    x = tl.load(x_ptr + offs, mask=mask, other=0)
    y = x * 2.0 - 1.0
    if MODE == 1:
        nv = tl.load(n_ptr).to(tl.int32)
        res = _cheb_eval(y, nv, nv, True)
    elif MODE == 2:
        nv = tl.load(n_ptr + offs, mask=mask, other=0).to(tl.int32)
        res = _cheb_eval(y, nv, tl.max(nv, axis=0), False)
    else:
        res = _cheb_eval(y, nval, nval, True)
    tl.store(out_ptr + offs, res.to(out_ptr.dtype.element_ty), mask=mask)


# Same contiguous kernel, but ``numel`` keeps Triton's divisibility
# specialisation (only ``nval`` is opted out).  When the element count is a
# multiple of 16 the compiler knows the mask bound is 16-aligned, which is what
# licenses 128-bit vector loads/stores.  Used for the mid-size band only, so the
# other bands keep their measured-best code.
@triton.jit(do_not_specialize=["nval"])
def _shifted_cheb_flat16(
    x_ptr, n_ptr, out_ptr, numel, nval, MODE: tl.constexpr, BLOCK: tl.constexpr
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    x = tl.load(x_ptr + offs, mask=mask, other=0)
    y = x * 2.0 - 1.0
    if MODE == 1:
        nv = tl.load(n_ptr).to(tl.int32)
        res = _cheb_eval(y, nv, nv, True)
    elif MODE == 2:
        nv = tl.load(n_ptr + offs, mask=mask, other=0).to(tl.int32)
        res = _cheb_eval(y, nv, tl.max(nv, axis=0), False)
    else:
        res = _cheb_eval(y, nval, nval, True)
    tl.store(out_ptr + offs, res.to(out_ptr.dtype.element_ty), mask=mask)


@triton.jit(do_not_specialize=["total", "nval"])
def _shifted_cheb_bc(
    x_ptr,
    n_ptr,
    out_ptr,
    total,
    nval,
    sx0,
    sx1,
    sx2,
    sx3,
    sx4,
    sx5,
    sx6,
    sx7,
    sn0,
    sn1,
    sn2,
    sn3,
    sn4,
    sn5,
    sn6,
    sn7,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    MODE: tl.constexpr,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """General strided / broadcasted case (rank <= 8)."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < total
    rem = offs
    zero = offs * 0
    xoff = zero
    noff = zero
    if RANK >= 8:
        i = rem % d7
        rem = rem // d7
        xoff += i * sx7
        noff += i * sn7
    if RANK >= 7:
        i = rem % d6
        rem = rem // d6
        xoff += i * sx6
        noff += i * sn6
    if RANK >= 6:
        i = rem % d5
        rem = rem // d5
        xoff += i * sx5
        noff += i * sn5
    if RANK >= 5:
        i = rem % d4
        rem = rem // d4
        xoff += i * sx4
        noff += i * sn4
    if RANK >= 4:
        i = rem % d3
        rem = rem // d3
        xoff += i * sx3
        noff += i * sn3
    if RANK >= 3:
        i = rem % d2
        rem = rem // d2
        xoff += i * sx2
        noff += i * sn2
    if RANK >= 2:
        i = rem % d1
        rem = rem // d1
        xoff += i * sx1
        noff += i * sn1
    xoff += rem * sx0
    noff += rem * sn0

    x = tl.load(x_ptr + xoff, mask=mask, other=0)
    y = x * 2.0 - 1.0
    if MODE == 1:
        nv = tl.load(n_ptr).to(tl.int32)
        res = _cheb_eval(y, nv, nv, True)
    elif MODE == 2:
        nv = tl.load(n_ptr + noff, mask=mask, other=0).to(tl.int32)
        res = _cheb_eval(y, nv, tl.max(nv, axis=0), False)
    else:
        res = _cheb_eval(y, nval, nval, True)
    tl.store(out_ptr + offs, res.to(out_ptr.dtype.element_ty), mask=mask)


def _align_strides(t, shape):
    """Right aligned strides of ``t`` for the broadcast ``shape`` (0 = repeat)."""
    rank = len(shape)
    strides = t.stride()
    tshape = t.shape
    offset = rank - len(tshape)
    res = [0] * _MAX_RANK
    for i in range(rank):
        j = i - offset
        if j < 0:
            continue
        if tshape[j] == 1 and shape[i] != 1:
            continue
        res[i] = strides[j]
    return res


def _general(x, n, nval, out_dt):
    """Strided / broadcast path.  ``n`` is a Tensor, or None for a python int."""
    if n is None:
        shape = x.shape
    else:
        shape = torch.broadcast_shapes(x.shape, n.shape)
    rank = len(shape)
    if rank > _MAX_RANK:
        raise UnsupportedDtypeError(
            "shifted_chebyshev_polynomial_t supports at most rank %d" % _MAX_RANK
        )
    out = torch.empty(shape, dtype=out_dt, device=x.device)
    total = out.numel()
    if total == 0:
        return out
    xs = _align_strides(x, shape)
    if n is None:
        ns = [0] * _MAX_RANK
        mode = 0
        narg = x
        degree = nval
    else:
        ns = _align_strides(n, shape)
        narg = n
        degree = 0
        mode = 1 if n.numel() == 1 else 2
    ds = [1] * (_MAX_RANK - 1)
    for j in range(1, rank):
        ds[j - 1] = shape[j]
    grid = ((total + _BLOCK - 1) // _BLOCK,)
    _shifted_cheb_bc[grid](
        x,
        narg,
        out,
        total,
        degree,
        xs[0],
        xs[1],
        xs[2],
        xs[3],
        xs[4],
        xs[5],
        xs[6],
        xs[7],
        ns[0],
        ns[1],
        ns[2],
        ns[3],
        ns[4],
        ns[5],
        ns[6],
        ns[7],
        ds[0],
        ds[1],
        ds[2],
        ds[3],
        ds[4],
        ds[5],
        ds[6],
        mode,
        rank,
        _BLOCK,
        num_warps=_NUM_WARPS,
    )
    return out


def _dispatch(kernel, x, n, out, total, nval, mode, block, div16):
    """Launch ``kernel`` and keep its compiled launcher for this specialisation."""
    nb = (total + block - 1) // block
    key = (
        kernel,
        x.get_device(),
        block,
        mode,
        nb,
        div16,
        x.dtype,
        n.dtype if isinstance(n, torch.Tensor) else None,
    )
    runner = _LAUNCH.get(key)
    if runner is not None:
        # A pointer that lost its 16-byte alignment may need a different
        # specialization, so it always takes the generic launch.
        if runner is not _NO_RUNNER and not ((x.data_ptr() | out.data_ptr()) & 15):
            runner(x, n, out, total, nval, mode, block)
            return
    kernel[(nb,)](x, n, out, total, nval, mode, block, num_warps=_NUM_WARPS)
    if runner is None:
        # First call for this specialization: capture the compiled launcher for
        # the following calls.  Any incompatibility leaves the generic path.
        try:
            _LAUNCH[key] = kernel.warmup(
                x, n, out, total, nval, mode, block, num_warps=_NUM_WARPS, grid=(1,)
            )[(nb, 1, 1)]
        except Exception:
            _LAUNCH[key] = _NO_RUNNER


def _launch_flat(x, n, out, total, nval, mode):
    if _MID_LO < total <= _SMALL_LIMIT:
        # Four elements per thread and a 16-aligned mask bound: the widest
        # access this backend can emit.
        _dispatch(
            _shifted_cheb_flat16,
            x,
            n,
            out,
            total,
            nval,
            mode,
            _BLOCK,
            (total & 15) == 0,
        )
        return
    block = _BLOCK_SMALL if total <= _SMALL_LIMIT else _BLOCK
    _dispatch(_shifted_cheb_flat, x, n, out, total, nval, mode, block, None)


def _run_int_scalar(x, n, out_dt):
    if x.is_contiguous():
        if out_dt is x.dtype:
            out = torch.empty_like(x)
        else:
            out = torch.empty(x.shape, dtype=out_dt, device=x.device)
        total = out.numel()
        if total:
            _launch_flat(x, x, out, total, n, 0)
        return out
    return _general(x, None, n, out_dt)


def _run_tensor(x, n, out_dt):
    xshape = x.shape
    nshape = n.shape
    if xshape == nshape and x.is_contiguous() and n.is_contiguous():
        if out_dt is x.dtype:
            out = torch.empty_like(x)
        else:
            out = torch.empty(xshape, dtype=out_dt, device=x.device)
        total = out.numel()
        if total:
            _launch_flat(x, n, out, total, 0, 2)
        return out
    if n.numel() == 1 and x.is_contiguous():
        if nshape == () or len(xshape) >= len(nshape):
            shape = xshape
        else:
            shape = torch.broadcast_shapes(xshape, nshape)
        if shape == xshape:
            if out_dt is x.dtype:
                out = torch.empty_like(x)
            else:
                out = torch.empty(shape, dtype=out_dt, device=x.device)
            total = out.numel()
            if total:
                _launch_flat(x, n, out, total, 0, 1)
            return out
    return _general(x, n, 0, out_dt)


def special_shifted_chebyshev_polynomial_t(x, n):
    _LOG.debug(_LOG_MSG)
    dt = x.dtype
    out_dt = _OUT_DTYPE.get(dt)
    if out_dt is None:
        if dt is torch.float16 or dt is torch.bfloat16:
            raise UnsupportedDtypeError(
                "Unsupported dtype %s: shifted_chebyshev_polynomial_t has no "
                "Half/BFloat16 implementation" % (dt,)
            )
        out_dt = torch.float32
    if isinstance(n, torch.Tensor):
        xshape = x.shape
        if xshape == n.shape and x.is_contiguous() and n.is_contiguous():
            out = (
                torch.empty_like(x)
                if out_dt is dt
                else torch.empty(xshape, dtype=out_dt, device=x.device)
            )
            total = out.numel()
            if total:
                _launch_flat(x, n, out, total, 0, 2)
            return out
        return _run_tensor(x, n, out_dt)
    if type(n) is int:
        return _run_int_scalar(x, n, out_dt)
    return _run_int_scalar(x, int(n), out_dt)
